#include <iostream>
#include <string>
#include <vector>

struct TrieNode {
    TrieNode* children[26] = {nullptr};
    bool isEnd = false;
};

class Trie {
    TrieNode root;
public:
    void insert(const std::string& word) {
        TrieNode* curr = &root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->children[idx]) curr->children[idx] = new TrieNode();
            curr = curr->children[idx];
        }
        curr->isEnd = true;
    }
    bool search(const std::string& word) {
        TrieNode* curr = &root;
        for (char c : word) {
            int idx = c - 'a';
            if (!curr->children[idx]) return false;
            curr = curr->children[idx];
        }
        return curr->isEnd;
    }
};

int main() {
    Trie t;
    t.insert("apple");
    std::cout << t.search("apple") << " " << t.search("app") << std::endl;
    return 0;
}

#include <iostream>

struct Node {
    int val;
    Node* left = nullptr;
    Node* right = nullptr;
    Node(int v) : val(v) {}
};

Node* lca(Node* root, int p, int q) {
    if (!root || root->val == p || root->val == q) return root;
    Node* l = lca(root->left, p, q);
    Node* r = lca(root->right, p, q);
    if (l && r) return root;
    return l ? l : r;
}

int main() {
    Node* root = new Node(3);
    root->left = new Node(5);
    root->right = new Node(1);
    Node* res = lca(root, 5, 1);
    std::cout << (res ? res->val : -1) << std::endl;
    return 0;
}
